const body = $input.first().json.body;
const required = ['brand_name', 'target_audience', 'channels', 'planning_period'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const channels = Array.isArray(body.channels) ? body.channels : body.channels.split(',').map(c=>c.trim()).filter(Boolean);
const postFreq = {};
channels.forEach(c => { postFreq[c] = (body.post_frequency && body.post_frequency[c]) ? parseInt(body.post_frequency[c]) : 3; });
return [{ json: {
  valid: true,
  brandName: body.brand_name.trim(),
  brandDescription: (body.brand_description || '').slice(0, 400),
  targetAudience: body.target_audience.trim().slice(0, 300),
  industry: body.industry || '',
  channels,
  postFrequency: postFreq,
  planningPeriod: body.planning_period.trim(),
  contentPillars: Array.isArray(body.content_pillars) ? body.content_pillars : (body.content_pillars||'').split(',').map(p=>p.trim()).filter(Boolean),
  tone: body.tone || 'informative and engaging',
  upcomingEvents: Array.isArray(body.upcoming_events) ? body.upcoming_events : (body.upcoming_events||'').split('\n').map(e=>e.trim()).filter(Boolean),
  competitors: Array.isArray(body.competitors) ? body.competitors : (body.competitors||'').split(',').map(c=>c.trim()).filter(Boolean),
  avoidTopics: (body.avoid_topics || '').slice(0, 200),
  replyEmail: body.reply_email || null
} }];

const trends = $('Research Trends').first().json?.results || [];
const input = $('Validate Input').first().json;
const trendContext = trends.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,250)}`).join('\n');
return [{ json: { input, trendContext } }];

values.content:
Build a content calendar.

Brand: {{ $json.input.brandName }}
Description: {{ $json.input.brandDescription || 'not provided' }}
Audience: {{ $json.input.targetAudience }}
Industry: {{ $json.input.industry || 'not specified' }}
Planning period: {{ $json.input.planningPeriod }}
Channels: {{ $json.input.channels.join(', ') }}
Post frequency: {{ JSON.stringify($json.input.postFrequency) }}
Content pillars: {{ $json.input.contentPillars.join(', ') || 'to be determined' }}
Tone: {{ $json.input.tone }}
Upcoming events/launches: {{ $json.input.upcomingEvents.join(', ') || 'none specified' }}
Competitors to watch: {{ $json.input.competitors.join(', ') || 'none specified' }}
Avoid: {{ $json.input.avoidTopics || 'nothing specified' }}

Trend context:
{{ $json.trendContext }}

Return this JSON:
{
  "calendar_overview": "2-3 sentences: strategy and themes for this period",
  "content_pillars_used": ["final list of content pillars with brief description of what each covers"],
  "posts": [
    {
      "week": "Week 1",
      "date_hint": "e.g. early in the period",
      "channel": "which platform",
      "pillar": "content pillar",
      "format": "e.g. carousel, reel, text post, article, thread",
      "hook": "the opening line or concept that earns attention",
      "content_idea": "what the post covers — specific enough to brief a writer or designer",
      "cta": "call to action if any",
      "notes": "any production notes or scheduling tips"
    }
  ],
  "content_mix_rationale": "why this balance of educational/promotional/engaging content suits this brand and period",
  "avoid_list": ["topics or formats to avoid for this brand in this period — based on industry, tone, and what was specified"],
  "repurposing_suggestions": ["2-3 ways to turn planned content into additional assets"]
}

