const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let calendar;
try { calendar = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
calendar._meta = { brandName: input.brandName, planningPeriod: input.planningPeriod, channels: input.channels, replyEmail: input.replyEmail };
return [{ json: calendar }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const channelColors = {linkedin:'#0077b5', twitter:'#1da1f2', instagram:'#e1306c', facebook:'#1877f2', tiktok:'#000', youtube:'#ff0000', blog:'#16a34a', email:'#7c3aed', newsletter:'#7c3aed', threads:'#000'};
const byWeek = {};
(c.posts||[]).forEach(p => { if (!byWeek[p.week]) byWeek[p.week] = []; byWeek[p.week].push(p); });
const weekBlocks = Object.entries(byWeek).map(([week, posts]) => {
  const postCards = posts.map(p => {
    const ch = p.channel ? p.channel.toLowerCase() : '';
    const color = Object.keys(channelColors).find(k => ch.includes(k)) ? channelColors[Object.keys(channelColors).find(k => ch.includes(k))] : '#6b7280';
    return `<div style="border-left:3px solid ${color};padding:12px 14px;background:#fafafa;border-radius:0 6px 6px 0;margin-bottom:10px">
      <div style="display:flex;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap">
        <span style="background:${color}22;color:${color};font-size:11px;font-weight:700;padding:2px 8px;border-radius:8px">${esc(p.channel)}</span>
        <span style="background:#f3f4f6;color:#6b7280;font-size:11px;padding:2px 8px;border-radius:8px">${esc(p.format||'')}</span>
        <span style="background:#eff6ff;color:#2563eb;font-size:11px;padding:2px 8px;border-radius:8px">${esc(p.pillar||'')}</span>
      </div>
      <div style="font-size:14px;font-weight:700;color:#1a1a1a;margin-bottom:4px">${esc(p.hook)}</div>
      <div style="font-size:13px;color:#374151;line-height:1.6;margin-bottom:4px">${esc(p.content_idea)}</div>
      ${p.cta?`<div style="font-size:12px;color:#16a34a">CTA: ${esc(p.cta)}</div>`:''}
      ${p.notes?`<div style="font-size:12px;color:#9ca3af;margin-top:3px">${esc(p.notes)}</div>`:''}
    </div>`;
  }).join('');
  return `<div style="margin-bottom:24px"><div style="font-size:13px;font-weight:700;text-transform:uppercase;color:#374151;border-bottom:2px solid #e5e7eb;padding-bottom:6px;margin-bottom:10px">${esc(week)}</div>${postCards}</div>`;
}).join('');
const pillars = (c.content_pillars_used||[]).map(p => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f3f4f6">${esc(p)}</div>`).join('');
const repurpose = (c.repurposing_suggestions||[]).map((r,i) => `<div style="font-size:13px;padding:5px 0;border-bottom:1px solid #f0fdf4;color:#166534">${i+1}. ${esc(r)}</div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:700px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;color:#6b7280;margin-bottom:4px">Content Calendar · ${esc(m.planningPeriod)}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.brandName)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">${(c.posts||[]).length} posts planned · ${m.channels.join(', ')}</div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <p style="font-size:14px;line-height:1.7;color:#374151;margin:0 0 10px">${esc(c.calendar_overview)}</p>
    <div style="font-size:13px;color:#6b7280;font-style:italic">${esc(c.content_mix_rationale)}</div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">${weekBlocks}</div>
  ${pillars?`<div style="background:#eff6ff;padding:14px 28px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:8px">Content pillars</div>
    ${pillars}
  </div>`:''}
  ${repurpose?`<div style="background:#f0fdf4;padding:14px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:8px">Repurposing ideas</div>
    ${repurpose}
  </div>`:''}
  <div style="background:#111827;color:#475569;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Content Calendar · ${esc(m.brandName)} · ${esc(m.planningPeriod)}
  </div>
</div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, brandName: m.brandName, postCount: (c.posts||[]).length, calendar: c } }];
